def is_not_prime(n):
    if n <= 1:
        return True
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return True
    return False

def heap_queue_largest(nums, k):
    import heapq
    heap = []
    for num in nums:
        heapq.heappush(heap, -num)
    result = []
    for _ in range(k):
        result.append(-heapq.heappop(heap))
    return result

