def rearange_string(s):
    # Count the frequency of each character in the string
    char_count = {}
    for char in s:
        char_count[char] = char_count.get(char, 0) + 1

    # Create a max heap based on character frequency
    max_heap = []
    for char, count in char_count.items():
        heapq.heappush(max_heap, (-count, char))

    # Build the rearranged string
    rearranged = []
    while len(max_heap) > 1:
        count1, char1 = heapq.heappop(max_heap)
        count2, char2 = heapq.heappop(max_heap)
        rearranged.extend([char1, char2])
        count1 += 1
        count2 += 1
        if count1 < 0:
            heapq.heappush(max_heap, (count1, char1))
        if count2 < 0:
            heapq.heappush(max_heap, (count2, char2))

    # If there's only one character left in the heap, append it to the rearranged string
    if max_heap:
        count, char = heapq.heappop(max_heap)
        rearranged.append(char)

    # Check if the rearranged string is valid
    for i in range(len(rearranged) - 1):
        if rearranged[i] == rearranged[i + 1]:
            return None

    return ''.join(rearranged)

